import numpy as np

def momentum_gradient_descent(f, grad_f, x0, learning_rate=0.01, momentum=0.9, max_iter=1000, tol=1e-6):
    x = x0.copy()
    velocity = np.zeros_like(x)
    history = [x.copy()]

    for i in range(max_iter):
        grad = grad_f(x)
        velocity = momentum * velocity + learning_rate * grad
        x = x - velocity
        history.append(x.copy())

        if np.linalg.norm(grad) < tol:
            break

    return x, history

def f(x):
    return x[0]**2 + 2*x[1]**2

def grad_f(x):
    return np.array([2*x[0], 4*x[1]])

x0 = np.array([3.0, 3.0])
x_opt, history = momentum_gradient_descent(f, grad_f, x0, learning_rate=0.1, momentum=0.9)
print(f"Optimal x: {x_opt}")
